INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'diet', 'n.', '/ˈdaɪət/', '日常饮食;规定饮食', 'A balanced diet should include fresh fruit and vegetables.', '均衡的饮食应该包含新鲜的水果和蔬菜。', 'Food for Thought', 1, 0, 'senior', 'wordlist', 'required2', 'U1', 'a balanced diet', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'cuisine', 'n.', '/kwɪˈziːn/', '烹饪(法);菜肴', 'When you travel, you should try the local cuisine.', '旅行时,你应该尝尝当地的菜肴。', 'Food for Thought', 2, 0, 'senior', 'wordlist', 'required2', 'U1', 'local cuisine', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'recipe', 'n.', '/ˈresɪpi/', '食谱;烹饪法', 'My grandmother taught me a simple recipe for chicken soup.', '我祖母教了我一个简单的鸡汤食谱。', 'Food for Thought', 3, 0, 'senior', 'wordlist', 'required2', 'U1', 'follow a recipe', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'chef', 'n.', '/ʃef/', '厨师;主厨', 'The chef in this restaurant cooks wonderful Sichuan dishes.', '这家餐馆的厨师做的川菜非常美味。', 'Food for Thought', 4, 0, 'senior', 'wordlist', 'required2', 'U1', 'a famous chef', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'recommend', 'v.', '/ˌrekəˈmend/', '推荐;建议', 'The waiter recommended the fish, and it was delicious.', '服务员推荐了这道鱼,味道很好。', 'Food for Thought', 5, 0, 'senior', 'wordlist', 'required2', 'U1', 'recommend a dish', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'snack', 'n.', '/snæk/', '小吃;点心;零食', 'An apple makes a healthy snack between meals.', '一个苹果是两餐之间健康的零食。', 'Food for Thought', 6, 0, 'senior', 'wordlist', 'required2', 'U1', 'a healthy snack', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'pudding', 'n.', '/ˈpʊdɪŋ/', '布丁;甜点', 'We had a warm rice pudding for dessert after dinner.', '晚饭后我们吃了一份热乎乎的米布丁作甜点。', 'Food for Thought', 7, 0, 'senior', 'wordlist', 'required2', 'U1', 'a rice pudding', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'steak', 'n.', '/steɪk/', '牛排;肉排;鱼排', 'He ordered a tender steak with a side of vegetables.', '他点了一份嫩牛排,还配了一份蔬菜。', 'Food for Thought', 8, 0, 'senior', 'wordlist', 'required2', 'U1', 'a tender steak', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sausage', 'n.', '/ˈsɒsɪdʒ/', '香肠;腊肠', 'Nothing beats my mother''s homemade sausage at breakfast.', '早餐时,没什么比得上我妈妈自制的香肠。', 'Food for Thought', 9, 0, 'senior', 'wordlist', 'required2', 'U1', 'homemade sausage', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'bacon', 'n.', '/ˈbeɪkən/', '咸猪肉;熏猪肉', 'A full English breakfast usually has fried bacon and eggs.', '一份全套英式早餐通常有煎咸肉和鸡蛋。', 'Food for Thought', 10, 0, 'senior', 'wordlist', 'required2', 'U1', 'fried bacon', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'toast', 'n.', '/təʊst/', '烤面包片;吐司', 'I like to eat toast with butter and honey in the morning.', '早上我喜欢吃涂了黄油和蜂蜜的烤面包片。', 'Food for Thought', 11, 0, 'senior', 'wordlist', 'required2', 'U1', 'toast with butter', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'butter', 'n.', '/ˈbʌtə/', '黄油;牛油', 'She spread some butter on the warm bread.', '她在热面包上抹了一些黄油。', 'Food for Thought', 12, 0, 'senior', 'wordlist', 'required2', 'U1', 'spread butter', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'cheese', 'n.', '/tʃiːz/', '干酪;奶酪', 'Blue cheese has a strong smell that you either love or hate.', '蓝纹奶酪气味很重,你要么爱它,要么恨它。', 'Food for Thought', 13, 0, 'senior', 'wordlist', 'required2', 'U1', 'blue cheese', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'tofu', 'n.', '/ˈtəʊfuː/', '豆腐', 'I was afraid to taste stinky tofu, but it was not so bad.', '我本来不敢尝臭豆腐,但其实没那么糟。', 'Food for Thought', 14, 0, 'senior', 'wordlist', 'required2', 'U1', 'stinky tofu', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'honey', 'n.', '/ˈhʌni/', '蜂蜜', 'Add a spoon of honey to make the yoghurt taste sweeter.', '加一勺蜂蜜,让酸奶尝起来更甜。', 'Food for Thought', 15, 0, 'senior', 'wordlist', 'required2', 'U1', 'a spoon of honey', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'yoghurt', 'n.', '/ˈjɒɡət/', '酸奶;酸乳', 'She had a bowl of fat-free yoghurt with fresh fruit.', '她吃了一碗加新鲜水果的脱脂酸奶。', 'Food for Thought', 16, 0, 'senior', 'wordlist', 'required2', 'U1', 'fat-free yoghurt', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'bakery', 'n.', '/ˈbeɪkəri/', '面包店;糕饼店', 'The small bakery on the corner sells fresh bread every morning.', '街角那家小面包店每天早上都卖新鲜面包。', 'Food for Thought', 17, 0, 'senior', 'wordlist', 'required2', 'U1', 'a small bakery', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'butcher', 'n.', '/ˈbʊtʃə/', '肉贩;卖肉的人', 'I went to the butcher''s shop to buy some pork for dinner.', '我去肉店买了些猪肉做晚饭。', 'Food for Thought', 18, 0, 'senior', 'wordlist', 'required2', 'U1', 'the butcher''s shop', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'honour', 'v.', '/ˈɒnə/', '向…表示敬意;尊敬', 'In China, people often cook many dishes to honour a guest.', '在中国,人们常做很多菜来款待客人。', 'Food for Thought', 19, 0, 'senior', 'wordlist', 'required2', 'U1', 'honour a guest', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'gather', 'v.', '/ˈɡæðə/', '聚集;集合;收集', 'The whole family gathers around the table for a big dinner.', '全家人围在桌旁享用一顿丰盛的晚餐。', 'Food for Thought', 20, 0, 'senior', 'wordlist', 'required2', 'U1', 'gather around', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'marriage', 'n.', '/ˈmærɪdʒ/', '婚姻;结婚', 'After their marriage, the couple learned to cook each other''s favourite food.', '婚后,这对夫妻学会了做对方最爱吃的菜。', 'Food for Thought', 21, 0, 'senior', 'wordlist', 'required2', 'U1', 'after their marriage', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'wedding', 'n.', '/ˈwedɪŋ/', '婚礼', 'At the wedding dinner, the guests were served eight special dishes.', '在婚宴上,客人们享用了八道特别的菜肴。', 'Food for Thought', 22, 0, 'senior', 'wordlist', 'required2', 'U1', 'a wedding dinner', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'custom', 'n.', '/ˈkʌstəm/', '风俗;习惯;传统', 'Eating dumplings at New Year is an old custom in the north.', '新年吃饺子是北方一个古老的风俗。', 'Food for Thought', 23, 0, 'senior', 'wordlist', 'required2', 'U1', 'an old custom', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'manners', 'n.', '/ˈmænəz/', '礼貌;礼仪;规矩', 'Good table manners mean you wait until everyone is served.', '良好的餐桌礼仪意味着你要等大家都上了菜再动筷。', 'Food for Thought', 24, 0, 'senior', 'wordlist', 'required2', 'U1', 'table manners', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'plate', 'n.', '/pleɪt/', '盘;碟', 'When you finish, place the knife and fork together on your plate.', '吃完后,把刀叉并排放在盘子上。', 'Food for Thought', 25, 0, 'senior', 'wordlist', 'required2', 'U1', 'a clean plate', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'tip', 'n.', '/tɪp/', '指点;建议;诀窍', 'Here are some useful tips for good table manners.', '这里有一些关于餐桌礼仪的实用建议。', 'Food for Thought', 26, 0, 'senior', 'wordlist', 'required2', 'U1', 'useful tips', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'trick', 'n.', '/trɪk/', '诀窍;技巧;戏法', 'The trick is to start with the knife and fork on the outside.', '诀窍是从最外侧的那副刀叉开始用。', 'Food for Thought', 27, 0, 'senior', 'wordlist', 'required2', 'U1', 'the trick is', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'opinion', 'n.', '/əˈpɪnjən/', '意见;看法;观点', 'In my opinion, this is the best noodle shop in town.', '在我看来,这是城里最好的面馆。', 'Food for Thought', 28, 0, 'senior', 'wordlist', 'required2', 'U1', 'in my opinion', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sort', 'n.', '/sɔːt/', '种;类;种类', 'My father does not enjoy this sort of strong-smelling food.', '我父亲不喜欢这种气味很重的食物。', 'Food for Thought', 29, 0, 'senior', 'wordlist', 'required2', 'U1', 'this sort of food', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'typical', 'adj.', '/ˈtɪpɪk(ə)l/', '典型的;有代表性的', 'A typical Sunday roast includes beef and roast vegetables.', '一顿典型的周日烤肉餐有牛肉和烤蔬菜。', 'Food for Thought', 30, 0, 'senior', 'wordlist', 'required2', 'U1', 'a typical dish', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'roast', 'adj.', '/rəʊst/', '烤制的;烤好的;(n.)大块烤肉', 'We all love roast beef with potatoes on a cold day.', '天冷时我们都爱吃配土豆的烤牛肉。', 'Food for Thought', 31, 0, 'senior', 'wordlist', 'required2', 'U1', 'roast beef', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'tender', 'adj.', '/ˈtendə/', '嫩的;软的(烹饪恰到好处)', 'The meat was so tender that it melted in the mouth.', '这肉非常嫩,入口即化。', 'Food for Thought', 32, 0, 'senior', 'wordlist', 'required2', 'U1', 'tender meat', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'bitter', 'adj.', '/ˈbɪtə/', '苦的;有苦味的', 'The sauce had a slightly bitter taste that I did not enjoy.', '这酱汁有一点苦味,我不太喜欢。', 'Food for Thought', 33, 0, 'senior', 'wordlist', 'required2', 'U1', 'a bitter taste', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'sour', 'adj.', '/saʊə/', '酸(味)的;馊的', 'This dish combines sweet and sour flavours in a clever way.', '这道菜巧妙地把甜味和酸味结合在一起。', 'Food for Thought', 34, 0, 'senior', 'wordlist', 'required2', 'U1', 'sweet and sour', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'salty', 'adj.', '/ˈsɔːlti/', '含盐的;咸的', 'The soup was too salty, so I added a little water.', '这汤太咸了,我加了点水。', 'Food for Thought', 35, 0, 'senior', 'wordlist', 'required2', 'U1', 'too salty', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'creamy', 'adj.', '/ˈkriːmi/', '似奶油的;软厚平滑的', 'The cheesecake was smooth and creamy with fresh strawberries.', '这块芝士蛋糕软滑细腻,还有新鲜草莓。', 'Food for Thought', 36, 0, 'senior', 'wordlist', 'required2', 'U1', 'smooth and creamy', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'slightly', 'adv.', '/ˈslaɪtli/', '略微;稍微', 'The meatball was cooked through but looked slightly pink inside.', '这肉丸熟透了,但里面看起来略带粉色。', 'Food for Thought', 37, 0, 'senior', 'wordlist', 'required2', 'U1', 'slightly pink', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'horrible', 'adj.', '/ˈhɒrəb(ə)l/', '糟糕的;可怕的;难闻的', 'At first the dish gave off a horrible smell, like an old shoe.', '起初这道菜散发出一股可怕的气味,像只旧鞋子。', 'Food for Thought', 38, 0, 'senior', 'wordlist', 'required2', 'U1', 'a horrible smell', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'satisfying', 'adj.', '/ˈsætɪsfaɪɪŋ/', '令人满意的;令人满足的', 'After a long day, a warm and satisfying meal is just perfect.', '忙碌了一天后,一顿温暖又满足的饭菜再好不过了。', 'Food for Thought', 39, 0, 'senior', 'wordlist', 'required2', 'U1', 'a satisfying meal', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'convenient', 'adj.', '/kənˈviːniənt/', '方便的;便利的', 'Ready meals are convenient, but fresh food is healthier.', '速食方便,但新鲜食物更健康。', 'Food for Thought', 40, 0, 'senior', 'wordlist', 'required2', 'U1', 'convenient ready meals', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'suffer', 'v.', '/ˈsʌfə/', '(身体或精神上)受苦;受折磨', 'Mum says we may suffer from too much heat if we eat lots of roast food.', '妈妈说,如果吃太多烤制食物,我们可能会上火。', 'Food for Thought', 41, 0, 'senior', 'wordlist', 'required2', 'U1', 'suffer from', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'resist', 'v.', '/rɪˈzɪst/', '忍住;抵挡;按捺', 'The smell of fresh bread is really hard to resist.', '新鲜面包的香味实在让人难以抗拒。', 'Food for Thought', 42, 0, 'senior', 'wordlist', 'required2', 'U1', 'hard to resist', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'adapt', 'v.', '/əˈdæpt/', '(使)适应;改编;调整', 'This recipe is easy to adapt to your own taste.', '这个食谱很容易根据你自己的口味来调整。', 'Food for Thought', 43, 0, 'senior', 'wordlist', 'required2', 'U1', 'adapt to taste', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'attack', 'v.', '/əˈtæk/', '侵袭;侵蚀;攻击', 'The sugar in soft drinks can attack the teeth for about twenty minutes.', '软饮料里的糖会侵蚀牙齿大约二十分钟。', 'Food for Thought', 44, 0, 'senior', 'wordlist', 'required2', 'U1', 'attack the teeth', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'belong', 'v.', '/bɪˈlɒŋ/', '属于;应被放在(某处)', 'Can you guess which fridge belongs to which person?', '你能猜出哪个冰箱属于哪个人吗?', 'Food for Thought', 45, 0, 'senior', 'wordlist', 'required2', 'U1', 'belong to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'download', 'v.', '/ˌdaʊnˈləʊd/', '下载(信息或程序)', 'You can download this app to help you choose healthy food.', '你可以下载这个应用,帮你挑选健康食物。', 'Food for Thought', 46, 0, 'senior', 'wordlist', 'required2', 'U1', 'download an app', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'addict', 'n.', '/ˈædɪkt/', '对…着迷的人;瘾君子', 'If you are a sugar addict, it is hard to say no to chocolate.', '如果你嗜糖如命,就很难拒绝巧克力。', 'Food for Thought', 47, 0, 'senior', 'wordlist', 'required2', 'U1', 'a sugar addict', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'poison', 'n.', '/ˈpɔɪz(ə)n/', '毒素;毒物;毒药', 'People say that one man''s meat is another man''s poison.', '人们说,甲之美食,乙之毒药。', 'Food for Thought', 48, 0, 'senior', 'wordlist', 'required2', 'U1', 'one man''s poison', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'function', 'n.', '/ˈfʌŋkʃ(ə)n/', '功能;作用;盛大的社交活动', 'The main function of breakfast is to give you energy for the day.', '早餐的主要功能是为你一天提供能量。', 'Food for Thought', 49, 0, 'senior', 'wordlist', 'required2', 'U1', 'the main function', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'differ', 'v.', '/ˈdɪfə/', '不同;不一样;有区别', 'Table manners differ from one country to another.', '餐桌礼仪因国家不同而有所差异。', 'Food for Thought', 50, 0, 'senior', 'wordlist', 'required2', 'U1', 'differ from', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f2u1.01', '①must / have to(表义务:内在必要 vs 外在要求)', 'A2', 10, '外研社版必修第二册 U1 — must 多表说话人自己强烈的必要或坚持;have to 多表规则、医嘱、客观情况等外部要求。两者都表示"必须做",在肯定的义务语境里成立,而 mustn''t(禁止)、needn''t / don''t have to(不必)与义务相反。', 1, 'required2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f2u1.02', '②should / ought to(表建议:应该做)', 'A2', 10, '外研社版必修第二册 U1 — should 和 ought to 都表示"应该",给出建议或忠告;语气比 must 弱。其相反面是 shouldn''t(不该这么做),而 mustn''t(禁止)、needn''t(不必)在给出"应该做某事"的语境里不成立。', 2, 'required2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f2u1.03', '③mustn''t / needn''t / don''t have to(禁止 vs 不必)', 'A2', 10, '外研社版必修第二册 U1 — mustn''t = 一定不要、禁止(不允许、危险或失礼);needn''t / don''t have to = 不必、没必要(做不做都行)。三者意义不同:禁止≠不必≠必须(must),据语境选唯一成立项。', 3, 'required2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'This soup is wonderful — you ____ try it before it gets cold!', 'must', 'mustn''t', 'needn''t', 'can''t', 'A', '说话人热情坚持对方一定要尝,用 must;禁止/不必/不能都与语境相反。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'We''ve run out of honey, so I ____ remember to buy some on the way home.', 'needn''t', 'must', 'mustn''t', 'don''t have to', 'B', '说话人提醒自己务必记得,内在必要用 must;其余表示不必或禁止,不合逻辑。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'The cake smells amazing. I really ____ ask the chef for the recipe.', 'mustn''t', 'needn''t', 'must', 'don''t have to', 'C', '出于自己的强烈意愿"一定要问",用 must。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'Grandma cooked all afternoon, so we ____ thank her for the lovely meal.', 'mustn''t', 'needn''t', 'can''t', 'must', 'D', '说话人觉得理应如此、非做不可,用 must;不必/禁止都不成立。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'You ____ taste this blue cheese — I''m sure you''ll love its strong flavour.', 'must', 'mustn''t', 'needn''t', 'shouldn''t', 'A', '强烈推荐对方一定要尝,用 must;mustn''t/shouldn''t 是反对,needn''t 是不必。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'I ____ say, this is the best noodle shop I have ever been to.', 'mustn''t', 'must', 'needn''t', 'can''t', 'B', '固定说法 I must say(我得说),表达强烈看法,用 must。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'It''s late and I''m starving — we ____ find somewhere to eat right now.', 'mustn''t', 'needn''t', 'must', 'don''t have to', 'C', '情况紧迫、非吃不可,内在强烈必要用 must。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'These dumplings are so good that I ____ have a second bowl.', 'mustn''t', 'needn''t', 'can''t', 'must', 'D', '说话人忍不住、一定要再来一碗,用 must。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'Before I forget it, I ____ write down Mum''s secret sauce recipe.', 'must', 'mustn''t', 'needn''t', 'shouldn''t', 'A', '提醒自己务必记下来,内在必要用 must。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'You ____ visit that little bakery; their fresh bread is unbeatable.', 'mustn''t', 'must', 'needn''t', 'can''t', 'B', '热情建议对方一定要去,用 must;其余与语境相反。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'To get a table at that restaurant, you ____ book a week in advance.', 'mustn''t', 'needn''t', 'have to', 'can''t', 'C', '这是餐厅的客观要求(外部规定),用 have to;禁止/不必/不能都不合理。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'I''m allergic to nuts, so I ____ check every label before I eat.', 'mustn''t', 'needn''t', 'don''t have to', 'have to', 'D', '因身体情况这一客观原因而不得不做,用 have to。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'The school rule says students ____ finish their vegetables before dessert.', 'have to', 'mustn''t', 'needn''t', 'can''t', 'A', '学校规定这一外部要求,用 have to。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'My doctor told me I ____ cut down on salt because of my blood pressure.', 'mustn''t', 'have to', 'needn''t', 'shouldn''t', 'B', '医嘱是外部要求,转述时用 have to。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'The recipe says you ____ heat the oil before adding the chillies.', 'mustn''t', 'needn''t', 'have to', 'can''t', 'C', '食谱的步骤要求(客观条件),用 have to。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'Because the canteen closes at two, we ____ have lunch a bit earlier today.', 'mustn''t', 'needn''t', 'don''t have to', 'have to', 'D', '受客观情况限制不得不提前,用 have to。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'In some cultures, guests ____ take off their shoes before a family dinner.', 'have to', 'mustn''t', 'needn''t', 'can''t', 'A', '当地风俗这一外部要求,用 have to。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'The waiter said we ____ pay at the counter, not at the table.', 'mustn''t', 'have to', 'needn''t', 'shouldn''t', 'B', '餐厅规定(外部要求),用 have to。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'Since every shop was closed, we ____ cook with whatever was left in the fridge.', 'mustn''t', 'needn''t', 'have to', 'can''t', 'C', '客观情况使然(没别的选择),用 have to。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.01'), 'All kitchen staff ____ wash their hands before they start work — it''s the rule.', 'mustn''t', 'needn''t', 'don''t have to', 'have to', 'D', '工作规定这一外部要求,用 have to。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'If you want to stay healthy, you ____ eat more fresh fruit and vegetables.', 'should', 'shouldn''t', 'mustn''t', 'needn''t', 'A', '给出健康建议"应该多吃",用 should;其余是反对或禁止。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'You look tired. You ____ have a proper breakfast every morning.', 'shouldn''t', 'should', 'mustn''t', 'needn''t', 'B', '友善建议对方应该这么做,用 should。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'These soft drinks have too much sugar; you ____ choose water instead.', 'shouldn''t', 'mustn''t', 'should', 'can''t', 'C', '建议改选更健康的水,用 should。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'If the soup tastes a little flat, you ____ add a pinch more salt.', 'shouldn''t', 'mustn''t', 'needn''t', 'should', 'D', '提出做法建议,用 should。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'When in Rome, you ____ try the local food and follow local customs.', 'should', 'shouldn''t', 'mustn''t', 'needn''t', 'A', '建议入乡随俗,用 should。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'To make the steak tender, you ____ cook it over a high heat first.', 'shouldn''t', 'should', 'mustn''t', 'can''t', 'B', '给出烹饪建议,用 should。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'You ____ wash the vegetables carefully before you put them in the pot.', 'shouldn''t', 'mustn''t', 'should', 'needn''t', 'C', '建议应当先洗净,用 should。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'If you don''t like spicy food, you ____ ask the chef to make it milder.', 'shouldn''t', 'mustn''t', 'needn''t', 'should', 'D', '提出解决建议,用 should。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'We ____ eat a little more slowly so that we can really enjoy the meal.', 'should', 'shouldn''t', 'mustn''t', 'can''t', 'A', '温和建议大家应该这么做,用 should。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'If you feel hungry between meals, you ____ keep some healthy snacks nearby.', 'shouldn''t', 'should', 'mustn''t', 'needn''t', 'B', '给出实用建议,用 should。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'Your fridge is almost empty; you ____ do a big shop this weekend.', 'shouldn''t', 'mustn''t', 'ought to', 'needn''t', 'C', '建议"应该"去采购,用 ought to,与 should 同义。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'Such a kind and skilful chef — we ____ leave him a nice review online.', 'shouldn''t', 'mustn''t', 'can''t', 'ought to', 'D', '理应这么做的建议,用 ought to。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'If you keep eating so much fried food, you ____ think about your health.', 'ought to', 'shouldn''t', 'mustn''t', 'needn''t', 'A', '提出忠告"应该考虑",用 ought to。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'This cheese is clearly going off; you ____ throw it away now.', 'shouldn''t', 'ought to', 'mustn''t', 'can''t', 'B', '建议应当扔掉,用 ought to。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'Guests are coming for dinner, so we ____ tidy the kitchen first.', 'shouldn''t', 'mustn''t', 'ought to', 'needn''t', 'C', '建议理应先收拾,用 ought to。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'If you want to learn to cook, you ____ start with a few simple recipes.', 'shouldn''t', 'mustn''t', 'needn''t', 'ought to', 'D', '给出学习建议,用 ought to。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'The bread is freshest now, so we ____ eat it today rather than tomorrow.', 'ought to', 'shouldn''t', 'mustn''t', 'can''t', 'A', '建议应当今天吃,用 ought to。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'You ____ taste the sauce before you add any more salt to it.', 'shouldn''t', 'ought to', 'mustn''t', 'needn''t', 'B', '给出做法建议,用 ought to。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'Since you are a vegetarian, you ____ tell the waiter about it in advance.', 'shouldn''t', 'mustn''t', 'ought to', 'can''t', 'C', '建议应当提前说明,用 ought to。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.02'), 'When a host invites us to dinner, we ____ thank them with a small gift.', 'shouldn''t', 'mustn''t', 'needn''t', 'ought to', 'D', '礼仪建议"理应"如此,用 ought to。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'These wild berries are poisonous, so you ____ eat them.', 'mustn''t', 'needn''t', 'don''t have to', 'must', 'A', '有毒、绝对不能吃,表禁止用 mustn''t;不必/必须都不合逻辑。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'You ____ touch the hot pot with your bare hands; you''ll burn yourself.', 'needn''t', 'mustn''t', 'don''t have to', 'can', 'B', '危险、千万不要,表禁止用 mustn''t。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'We ____ be late for the wedding dinner; it would be very rude.', 'needn''t', 'don''t have to', 'mustn''t', 'must', 'C', '失礼、一定不要迟到,表禁止用 mustn''t。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'You ____ put metal plates in the microwave — it is really dangerous.', 'needn''t', 'don''t have to', 'should', 'mustn''t', 'D', '危险、绝不可这么做,用 mustn''t。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'Diners ____ smoke inside the restaurant; it is simply not allowed.', 'mustn''t', 'needn''t', 'don''t have to', 'can', 'A', '明令不允许,表禁止用 mustn''t。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'You ____ tell Grandma the soup was too salty; it would hurt her feelings.', 'needn''t', 'mustn''t', 'don''t have to', 'must', 'B', '千万别说出口,表禁止/劝阻用 mustn''t。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'Young children ____ play with the sharp kitchen knives.', 'needn''t', 'don''t have to', 'mustn''t', 'can', 'C', '为安全绝对禁止,用 mustn''t。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'You ____ leave the gas on after you finish cooking; it''s not safe.', 'needn''t', 'don''t have to', 'should', 'mustn''t', 'D', '不安全、绝不可,用 mustn''t。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'There''s plenty of food in the fridge, so you ____ cook anything tonight.', 'needn''t', 'mustn''t', 'must', 'can''t', 'A', '没必要做,表不必用 needn''t;禁止/必须都不合语境。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'The meal has already been paid for, so you ____ bring any money.', 'mustn''t', 'needn''t', 'must', 'can''t', 'B', '无需带钱,表不必用 needn''t。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'It''s only a casual lunch, so you ____ wear anything fancy.', 'mustn''t', 'must', 'needn''t', 'should', 'C', '无需穿正式,表不必用 needn''t。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'Mum said, "You ____ try the stinky tofu if you really don''t want to."', 'mustn''t', 'must', 'can''t', 'needn''t', 'D', '不想吃就不必吃,表不必用 needn''t。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'We have enough chairs, so we ____ borrow any from the neighbours.', 'needn''t', 'mustn''t', 'must', 'can''t', 'A', '无需去借,表不必用 needn''t。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'The dish is very forgiving, so you ____ follow the recipe exactly.', 'mustn''t', 'needn''t', 'must', 'should', 'B', '不必严格照做,表不必用 needn''t。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'Lunch is free for students today, so you ____ pay for it.', 'mustn''t', 'must', 'don''t have to', 'can''t', 'C', '免费、无需付钱,表不必用 don''t have to。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'There is still some bread left, so we ____ buy more this morning.', 'mustn''t', 'must', 'can''t', 'don''t have to', 'D', '还有剩、不必再买,用 don''t have to。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'It''s a buffet, so you ____ wait to be served at the table.', 'don''t have to', 'mustn''t', 'must', 'should', 'A', '自助餐无需等人上菜,用 don''t have to。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'She isn''t coming for dinner tonight, so we ____ cook for her.', 'mustn''t', 'don''t have to', 'must', 'can''t', 'B', '她不来、无需为她做,用 don''t have to。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'The soup is quite mild, so you ____ worry about it being too spicy.', 'mustn''t', 'must', 'don''t have to', 'should', 'C', '不必担心,用 don''t have to。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U1' AND code='f2u1.03'), 'We''ve already booked a table, so we ____ queue outside the restaurant.', 'mustn''t', 'must', 'can''t', 'don''t have to', 'D', '已订位、无需排队,用 don''t have to。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Child of Two Kitchens', 'I grew up in England with a British father and a Chinese mother, so two very different kitchens shaped me. Ever since I could hold a knife and fork, and chopsticks too, I have enjoyed food from both countries. My mother often cooks spicy dishes from her home town, and thanks to her my father has even come to love hot pot. Still, there are some dishes he dare not try. He was shocked the first time he saw how the Chinese eat almost every part of an animal, and even today he will not happily eat chicken feet. I am the opposite. I once asked a butcher for pigs'' ears, and he must have thought I was joking. To me, the best thing of all is a cross-cultural afternoon tea: English biscuits with a cup of Chinese tea in a fine china cup.', '记叙·跨文化成长的饮食故事', 144, '[{"q":"Why has the writer enjoyed food from two countries since childhood?","answer":"A","options":["Each of the writer''s parents comes from a different food culture.","The writer was trained to be a professional cook.","The family ran a restaurant in two countries.","The writer disliked all English dishes as a child."],"explanation":"文章说作者有英国父亲和中国母亲,两种厨房塑造了他;干扰项均无依据。"},{"q":"What is the father''s attitude to some Chinese dishes?","answer":"B","options":["He happily eats every part of an animal.","He still avoids certain dishes such as chicken feet.","He now refuses to eat any Chinese food.","He prefers them to his own English food."],"explanation":"父亲至今仍不愿吃鸡爪之类,说明他对某些菜仍有保留。"},{"q":"What does the writer enjoy most?","answer":"A","options":["A mix of English and Chinese habits at tea time.","Cooking spicy food for the whole family.","Visiting a butcher''s shop every week.","Eating only traditional British meals."],"explanation":"结尾说作者最爱跨文化下午茶——英式饼干配中国茶,体现两种文化的融合。"}]'::jsonb, '[{"word":"chopsticks","cn":"筷子"},{"word":"hot pot","cn":"火锅"},{"word":"butcher","cn":"肉贩"}]'::jsonb, 2, 'required2', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Table Manners Around the World', 'Going on your first trip abroad is exciting, but new customs can also be confusing, and table manners are no exception. In Britain, it is polite to wait until everyone has been served before you start eating. When there are many knives and forks, the trick is simple: start with the ones on the outside and work inwards. After the meal, you should place your knife and fork together on the plate, with the handles pointing to the four o''clock position. Yet manners differ from place to place. In some countries you must use a knife and fork even for a hamburger, while in others people happily eat with their hands. The golden rule is the old saying: when in Rome, do as the Romans do. If you watch your hosts carefully and follow what they do, you needn''t worry too much, and you will soon enjoy the local food with confidence.', '说明·各地餐桌礼仪的差异', 152, '[{"q":"What should you do with many knives and forks on the table?","answer":"B","options":["Pick up whichever one is closest to the plate.","Begin with the outer ones and move inwards.","Use only the knife and leave the forks.","Wait for the waiter to hand you one."],"explanation":"文中诀窍是从最外侧的刀叉开始,逐渐向内,即先用外侧。"},{"q":"What does the writer suggest doing in a foreign country?","answer":"C","options":["Always insist on your own country''s habits.","Refuse any food eaten with the hands.","Follow the way your hosts behave at the table.","Leave the table before others finish."],"explanation":"作者引用入乡随俗,建议留心并模仿主人的做法。"},{"q":"What is the writer''s main point about table manners?","answer":"D","options":["They are exactly the same everywhere.","They matter only at formal dinners.","They are too difficult to ever learn.","They change from one place to another."],"explanation":"文章强调礼仪因地而异,故主旨是\"各地不同\"。"}]'::jsonb, '[{"word":"manners","cn":"礼仪;礼貌"},{"word":"trick","cn":"诀窍"},{"word":"handle","cn":"柄;把手"}]'::jsonb, 2, 'required2', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Foods You Love or Hate', 'Some foods seem to divide people into two groups: those who love them and those who cannot stand them. Stinky tofu is a famous example. At first it looks like a horrible grey block and smells a little like an old shoe, so many visitors dare not taste it. Yet those who are brave enough often find that the taste is far better than the smell. Blue cheese works in much the same way. Its strong smell puts some people off completely, while others think it is one of the finest foods in the world. Why do these foods make us feel so differently? Part of the answer is what we grow up eating. A child who tastes a food often from an early age usually comes to enjoy it, while a stranger may find the very same food shocking. As the old saying goes, one man''s meat is another man''s poison.', '说明·气味浓烈的食物', 152, '[{"q":"What surprises brave people who taste stinky tofu?","answer":"A","options":["It actually tastes better than it smells.","It is much cheaper than they expected.","It has no smell at all.","It looks exactly like blue cheese."],"explanation":"勇于尝试的人发现味道远好于气味,是文章的关键点。"},{"q":"According to the writer, why do people feel so differently about such foods?","answer":"B","options":["Because the foods are sold only in one country.","Largely because of what they ate while growing up.","Because they are always too expensive.","Because doctors tell them which to eat."],"explanation":"作者指出,从小常吃某种食物的人往往会喜欢它,这是差异的部分原因。"},{"q":"What does the saying at the end help to show?","answer":"C","options":["Strong-smelling food is always bad for health.","Everyone should eat the same kind of food.","People''s tastes in food can be very different.","Cheese is more popular than tofu."],"explanation":"\"甲之美食,乙之毒药\"说明人们口味差异极大。"}]'::jsonb, '[{"word":"tofu","cn":"豆腐"},{"word":"poison","cn":"毒物;毒药"},{"word":"horrible","cn":"糟糕的;难闻的"}]'::jsonb, 2, 'required2', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Full English Breakfast', 'Ask people in Britain about their favourite weekend meal, and many will mention the full English breakfast. A typical plate holds fried bacon and eggs, sausages, beans and toast with butter, and sometimes a grilled tomato as well. It is a heavy, satisfying meal that is meant to keep you going for hours, which is why it became popular among workers long ago. Today most families are too busy to cook it during the week, so it has become a treat for lazy weekend mornings. On Sundays, many homes also enjoy a roast, with roast beef and vegetables. Some people warn that eating so much fried and roast food is not very healthy, and that we ought to balance it with fresh fruit and salad. Even so, for a cold and rainy morning, few meals feel as warm and welcoming as a full English breakfast shared with the family.', '说明·英式早餐的传统', 149, '[{"q":"Why did the full English breakfast first become popular?","answer":"D","options":["It was the cheapest meal in the country.","It contained no meat at all.","It could only be made on Sundays.","It was a filling meal that kept workers going."],"explanation":"文中说这顿饭分量足、能让人撑很久,因此早年在工人中流行。"},{"q":"When do most families have this breakfast nowadays?","answer":"A","options":["As a relaxed treat at the weekend.","Every single morning before work.","Only at large family weddings.","Never, because it is now forbidden."],"explanation":"如今家庭太忙,平日不做,它成了周末悠闲早晨的享受。"},{"q":"What advice does the writer give about such meals?","answer":"B","options":["Eat them at every meal of the day.","Add fresh fruit and salad to keep a balance.","Avoid all cooked food completely.","Replace them with sweets and cola."],"explanation":"作者提醒应当用新鲜水果和沙拉来平衡油炸烤制食物。"}]'::jsonb, '[{"word":"bacon","cn":"咸肉"},{"word":"sausage","cn":"香肠"},{"word":"roast","cn":"烤制的;烤肉"}]'::jsonb, 2, 'required2', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Story of Gong Bao Chicken', 'Gong Bao Chicken, also known as Kung Pao Chicken, is one of the best-loved dishes in Chinese restaurants around the world. It was first a family dish of Ding Baozhen, a high-ranking court official in the Qing Dynasty who once helped repair a famous irrigation system in Sichuan. Over the years his home recipe spread far beyond his family table and became famous everywhere. The dish is not hard to make. You heat the oil, add dried chillies and spring onions, then cook the chicken through before adding soy sauce, vinegar, sugar, peanuts and a little tofu. What makes it so hard to resist is the clever mix of spicy, salty, sweet and sour flavours all in one bowl. Better still, the recipe is easy to adapt to your own taste, so cooks everywhere can make it a little hotter, sweeter or milder, just the way they and their families like it.', '说明·一道名菜的来历与做法', 152, '[{"q":"Who was Gong Bao Chicken first connected with?","answer":"C","options":["A foreign chef visiting China.","A famous Sichuan farmer.","A senior official of the Qing Dynasty.","A modern restaurant owner."],"explanation":"它最初是清朝高官丁宝桢的家常菜。"},{"q":"What makes the dish so hard to resist?","answer":"D","options":["Its bright red colour.","Its very low price.","The fact that it takes hours to cook.","The clever blend of several different flavours."],"explanation":"辣、咸、甜、酸几种味道巧妙结合,使它令人难以抗拒。"},{"q":"Why can cooks everywhere enjoy making it?","answer":"A","options":["The recipe can easily be changed to suit each cook.","It needs no cooking at all.","Only restaurants are allowed to make it.","It always tastes exactly the same."],"explanation":"食谱容易根据个人口味调整,所以各地厨师都能做出自己喜欢的味道。"}]'::jsonb, '[{"word":"official","cn":"官员"},{"word":"recipe","cn":"食谱"},{"word":"resist","cn":"抗拒;忍住"}]'::jsonb, 2, 'required2', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'You Are What You Eat', 'Is there any truth behind the saying "You are what you eat"? A magazine once asked five people to open their fridges and talk about their lives. The results were surprising. A busy junior doctor often felt too tired to cook and ended up living on toast and yoghurt, though she knew she ought to change. A chef with five children rarely cooked at home and filled his freezer with ready meals, simply because they were so convenient. A young couple who avoided all animal products kept their fridge full of fresh, seasonal fruit and vegetables. What people choose to eat, the writer argues, says a great deal about how they live. A fridge can act like a kind of mirror. If we want to eat more healthily, the first step is honest: open the door, look inside, and ask ourselves whether our daily food really matches the life we hope to lead.', '议论·饮食与生活方式', 153, '[{"q":"Why did the chef rely on ready meals?","answer":"B","options":["He did not know how to cook at all.","He found them quick and easy to use.","He disliked fresh fruit and vegetables.","His children refused to eat home cooking."],"explanation":"厨师因为速食方便而很少在家做饭。"},{"q":"What kind of food filled the young couple''s fridge?","answer":"C","options":["Lots of frozen ready meals.","Toast and yoghurt only.","Fresh fruit and vegetables of the season.","Large amounts of meat."],"explanation":"这对不吃任何动物制品的年轻夫妻,冰箱里装满应季新鲜果蔬。"},{"q":"What is the main message of the passage?","answer":"D","options":["Everyone should become a vegetarian.","Fridges should always be kept full.","Cooking at home is a waste of time.","What we eat reflects how we live."],"explanation":"全文论点是:吃什么反映了人怎样生活,冰箱像一面镜子。"}]'::jsonb, '[{"word":"yoghurt","cn":"酸奶"},{"word":"convenient","cn":"方便的"},{"word":"belong","cn":"属于"}]'::jsonb, 2, 'required2', 'U1', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U1', 'A Meal Out', 'Last Saturday my family decided to (1)____ at a new restaurant in town. We had to (2)____ a table in advance because the place was always full. When we arrived, a friendly waiter (3)____ us to a quiet corner. He (4)____ the fish, saying it was the chef''s best dish, so we ordered it. While we waited, we read the (5)____ and chatted happily. The food was worth the wait. My steak was so (6)____ that it almost melted in my mouth, and the sauce had a lovely sweet and (7)____ taste. My little brother, who is a real sugar (8)____, was delighted by the chocolate pudding. When we finished, Dad placed his knife and fork together on his (9)____, just as good manners require. We all agreed it had been a truly (10)____ evening.', 135, 2, '[{"q":"1","answer":"A","options":["eat","sleep","drive","sing"],"explanation":"decide to eat at a restaurant 去餐厅吃饭。"},{"q":"2","answer":"B","options":["lose","book","break","wash"],"explanation":"book a table 预订餐桌。"},{"q":"3","answer":"C","options":["sold","threw","showed","cleaned"],"explanation":"show sb to a corner 把某人领到角落。"},{"q":"4","answer":"D","options":["refused","forgot","dropped","recommended"],"explanation":"服务员推荐这道鱼,用 recommend。"},{"q":"5","answer":"A","options":["menu","weather","homework","ticket"],"explanation":"等餐时读菜单 menu。"},{"q":"6","answer":"B","options":["hard","tender","cold","loud"],"explanation":"肉嫩到入口即化,用 tender。"},{"q":"7","answer":"C","options":["heavy","dark","sour","quiet"],"explanation":"sweet and sour 甜酸味。"},{"q":"8","answer":"D","options":["teacher","driver","farmer","addict"],"explanation":"a sugar addict 嗜糖的人。"},{"q":"9","answer":"A","options":["plate","chair","phone","window"],"explanation":"把刀叉放在盘子上,用 plate。"},{"q":"10","answer":"B","options":["boring","satisfying","terrible","empty"],"explanation":"美好满足的一晚,用 satisfying。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U1', 'Cooking with Grandma', 'Every summer I visit my grandmother, who is a wonderful (1)____. She believes that the best way to learn is to (2)____ her in the kitchen. On my first morning, she handed me an old (3)____ for noodle soup that her own mother had used. "Just (4)____ the steps one by one," she said with a smile. First we washed and cut the (5)____, then heated some oil in a large pot. Grandma told me I needn''t (6)____ about making mistakes, because every cook learns by doing. The kitchen soon filled with a (7)____ smell that made me hungry. When the soup was ready, it tasted a little too (8)____, so we added some water. Grandma said good food should never be too (9)____. That morning with her was the most (10)____ lesson of my whole holiday.', 137, 2, '[{"q":"1","answer":"C","options":["driver","singer","cook","doctor"],"explanation":"奶奶很会做饭,是位 cook。"},{"q":"2","answer":"D","options":["leave","ignore","sell","join"],"explanation":"join her in the kitchen 在厨房里和她一起。"},{"q":"3","answer":"A","options":["recipe","ticket","map","letter"],"explanation":"面汤的食谱 recipe。"},{"q":"4","answer":"B","options":["break","follow","forget","lose"],"explanation":"follow the steps 按步骤来。"},{"q":"5","answer":"C","options":["clothes","books","vegetables","windows"],"explanation":"洗切蔬菜 vegetables。"},{"q":"6","answer":"D","options":["hear","shout","cook","worry"],"explanation":"needn''t worry about 不必担心。"},{"q":"7","answer":"A","options":["wonderful","terrible","silent","empty"],"explanation":"诱人的香味让我饿了,用 wonderful。"},{"q":"8","answer":"B","options":["loud","salty","bright","fast"],"explanation":"太咸了才加水,用 salty。"},{"q":"9","answer":"C","options":["quiet","wide","heavy","late"],"explanation":"好的饭菜不应太油腻/厚重,用 heavy。"},{"q":"10","answer":"D","options":["boring","terrible","empty","useful"],"explanation":"最有用的一课,用 useful。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U1', 'A Healthier Canteen', 'Our school canteen used to sell a lot of fried food and sweet (1)____. Many students loved them, but the doctor warned that too much sugar can (2)____ our teeth. Last term, the head teacher decided to (3)____ some changes. Now the canteen offers more fresh (4)____ and salad every day. Sugary cola has been replaced with water and fruit (5)____. At first some students were unhappy, and a few even (6)____ about the new menu. But slowly they began to (7)____ the lighter meals. One boy said he used to feel sleepy in the afternoon, but now he has much more (8)____. The cooks also put up friendly (9)____ to help us choose well, such as "Try something green today!" In my (10)____, a healthy canteen is one of the best gifts a school can give.', 137, 2, '[{"q":"1","answer":"A","options":["snacks","clothes","toys","books"],"explanation":"油炸食物和甜点心 snacks。"},{"q":"2","answer":"B","options":["help","attack","clean","open"],"explanation":"糖会侵蚀牙齿,用 attack。"},{"q":"3","answer":"C","options":["lose","forget","make","sell"],"explanation":"make some changes 做出改变。"},{"q":"4","answer":"D","options":["paper","music","noise","fruit"],"explanation":"新鲜水果和沙拉,用 fruit。"},{"q":"5","answer":"A","options":["juice","smoke","dust","sand"],"explanation":"fruit juice 果汁。"},{"q":"6","answer":"B","options":["cheered","complained","slept","sang"],"explanation":"对新菜单抱怨,用 complain。"},{"q":"7","answer":"C","options":["refuse","drop","enjoy","break"],"explanation":"渐渐喜欢上清淡的饭菜,用 enjoy。"},{"q":"8","answer":"D","options":["homework","money","rain","energy"],"explanation":"下午更有精力,用 energy。"},{"q":"9","answer":"A","options":["signs","shoes","plates","chairs"],"explanation":"贴出友好的提示牌,用 signs。"},{"q":"10","answer":"B","options":["garden","opinion","kitchen","pocket"],"explanation":"In my opinion 在我看来。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U1', 'My First Durian', 'During a trip to South-east Asia, my friend dared me to (1)____ a durian, a fruit famous for its strong smell. The moment the seller cut it open, a (2)____ smell filled the air, and I almost changed my mind. "You needn''t eat it if you don''t (3)____ to," my friend laughed. But I gathered all my (4)____ and took a small bite. To my surprise, the soft yellow flesh was sweet and (5)____, a little like custard. The terrible smell and the lovely (6)____ did not seem to match at all. Local people clearly (7)____ this fruit, and now I understood why. My friend told me that durian is so (8)____ that some hotels do not allow it inside. As we walked on, I could not (9)____ buying one more piece. That day taught me never to judge a food only by its (10)____.', 145, 2, '[{"q":"1","answer":"C","options":["sell","cook","try","drop"],"explanation":"敢不敢尝一尝,用 try。"},{"q":"2","answer":"D","options":["lovely","quiet","bright","horrible"],"explanation":"难闻的气味,用 horrible。"},{"q":"3","answer":"A","options":["want","hear","run","sleep"],"explanation":"if you don''t want to 如果你不想。"},{"q":"4","answer":"B","options":["money","courage","clothes","paper"],"explanation":"鼓起全部勇气,用 courage。"},{"q":"5","answer":"C","options":["sour","salty","creamy","loud"],"explanation":"像奶冻一样软滑,用 creamy。"},{"q":"6","answer":"D","options":["noise","weather","price","taste"],"explanation":"难闻气味与美味口感不匹配,用 taste。"},{"q":"7","answer":"A","options":["loved","hated","feared","lost"],"explanation":"当地人显然很喜欢这水果,用 love。"},{"q":"8","answer":"B","options":["sweet","smelly","quiet","cheap"],"explanation":"因气味太大才被旅馆禁止,用 smelly。"},{"q":"9","answer":"C","options":["start","begin","resist","enjoy"],"explanation":"could not resist 忍不住又买,用 resist。"},{"q":"10","answer":"D","options":["price","size","colour","smell"],"explanation":"不要只凭气味来评判食物,用 smell。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U1', 'Afternoon Tea', 'Afternoon tea is a much-loved British (1)____ that began almost two hundred years ago. The story goes that a duchess often felt hungry in the late afternoon and asked for tea with a small (2)____ to keep her going until dinner. Soon her friends (3)____ the idea, and the habit spread across the country. A traditional afternoon tea is served on a special (4)____ with three levels. The bottom holds small sandwiches, the middle holds warm cakes with butter and (5)____, and the top holds sweet treats. Of course, a good cup of tea is the most important (6)____ of all. Today many hotels still (7)____ afternoon tea to their guests, and it has become a special (8)____ for birthdays and family visits. You needn''t be rich to enjoy it; you can easily make a simple (9)____ at home. In my view, it is one of the most charming food (10)____ in the world.', 154, 2, '[{"q":"1","answer":"A","options":["custom","weather","animal","building"],"explanation":"一种深受喜爱的英国风俗,用 custom。"},{"q":"2","answer":"B","options":["garden","snack","ticket","river"],"explanation":"配茶的小点心,用 snack。"},{"q":"3","answer":"C","options":["refused","lost","copied","sold"],"explanation":"朋友们效仿这个主意,用 copy。"},{"q":"4","answer":"D","options":["road","cloud","river","tray"],"explanation":"三层的托盘,用 tray。"},{"q":"5","answer":"A","options":["honey","sand","paper","stone"],"explanation":"涂黄油和蜂蜜的蛋糕,用 honey。"},{"q":"6","answer":"B","options":["noise","part","price","size"],"explanation":"最重要的部分,用 part。"},{"q":"7","answer":"C","options":["refuse","forget","offer","lose"],"explanation":"酒店向客人提供下午茶,用 offer。"},{"q":"8","answer":"D","options":["problem","mistake","danger","treat"],"explanation":"成为一种特别的款待/享受,用 treat。"},{"q":"9","answer":"A","options":["meal","engine","machine","signal"],"explanation":"在家做一顿简单的下午茶餐,用 meal。"},{"q":"10","answer":"B","options":["engines","customs","animals","machines"],"explanation":"最迷人的饮食传统之一,用 customs。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U1', 'A New Café', 'As a food blogger, I am always looking for somewhere new to (1)____. Last week I tried a small café that had just opened near my home. The moment I walked in, I loved the warm and friendly (2)____. The young owner, who used to work as a (3)____ in a big hotel, now bakes everything himself. I (4)____ his fresh bread, which was still warm from the oven. I also ordered a slice of cake that was wonderfully smooth and (5)____, with fresh fruit on top. Best of all, the prices were very (6)____, so anyone could afford a treat. I asked the owner for the (7)____ of his famous lemon cake, but he just smiled and kept it a secret. Before I left, he gave me a free (8)____ of chocolate to try. I will certainly (9)____ this lovely café to my readers, and I cannot (10)____ to go back again.', 153, 2, '[{"q":"1","answer":"C","options":["sleep","drive","eat","paint"],"explanation":"美食博主到处找地方吃,用 eat。"},{"q":"2","answer":"D","options":["winter","danger","noise","welcome"],"explanation":"温暖友好的欢迎气氛,用 welcome。"},{"q":"3","answer":"A","options":["chef","farmer","driver","pilot"],"explanation":"曾在大酒店当厨师,用 chef。"},{"q":"4","answer":"B","options":["sold","tried","dropped","threw"],"explanation":"尝了他的新鲜面包,用 try。"},{"q":"5","answer":"C","options":["salty","bitter","creamy","loud"],"explanation":"细腻软滑的蛋糕,用 creamy。"},{"q":"6","answer":"D","options":["tall","loud","dark","low"],"explanation":"价格很低,人人买得起,用 low。"},{"q":"7","answer":"A","options":["recipe","weather","ticket","engine"],"explanation":"向店主要柠檬蛋糕的食谱,用 recipe。"},{"q":"8","answer":"B","options":["river","piece","road","cloud"],"explanation":"一块免费的巧克力,用 piece。"},{"q":"9","answer":"C","options":["refuse","forget","recommend","hide"],"explanation":"向读者推荐这家咖啡馆,用 recommend。"},{"q":"10","answer":"D","options":["stop","drive","sleep","wait"],"explanation":"cannot wait to 迫不及待,用 wait。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·对话 Ordering a Healthy Lunch', '外研社版必修第二册 U1 · dialogue', 3, 'Janet: I think I''ll have a double hamburger with chips and a large cola.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·独白 A Tip on Table Manners', '外研社版必修第二册 U1 · passage', 2, 'Good evening, and welcome to our short guide on table manners. Here is one simple rule that works almost everywhere: wait until everyone at the table has been served before you start to eat. It shows respect for the people around you. If there are many knives and forks, don''t worry. Just start with the ones on the outside and work your way in. And when you have finished, place your knife and fork together on your plate. Remember, you needn''t be perfect — just watch your host and follow what they do.', '餐桌礼仪小贴士:几乎处处适用的一条简单规则是,等桌上每个人都上了菜再动筷,这是对周围人的尊重;若刀叉很多,从最外侧开始向内用;吃完后把刀叉并排放在盘子上;不必做到完美,只要留心并模仿主人的做法即可。', 'uk_male', '[{"q":"What should you do before you start eating?","type":"choice","answer":"D","options":["Start as soon as you sit down.","Ask the waiter for more food.","Finish your drink first.","Wait until everyone has been served."]},{"q":"Which knife and fork should you pick up first?","type":"choice","answer":"A","options":["The ones on the outside.","The ones nearest the plate.","Any one you like.","The largest one."]},{"q":"What should you do when you finish?","type":"choice","answer":"B","options":["Leave them on the table.","Place the knife and fork together on the plate.","Hand them to the host.","Wash them yourself."]},{"q":"What does waiting for others show?","type":"choice","answer":"C","options":["That you are not hungry.","That the food is bad.","Respect for the people around you.","That you are in a hurry."]},{"q":"What is the speaker''s final advice?","type":"choice","answer":"D","options":["Always eat very quickly.","Bring your own knife and fork.","Never use a fork.","Watch your host and do as they do."]}]'::jsonb, '[]'::jsonb, 'short', 'required2', 'U1', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·对话 Choosing Dishes at a Restaurant', '外研社版必修第二册 U1 · dialogue', 3, 'Tom: This menu looks great, but I really can''t decide what to have.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·独白 How to Make Quick Fried Rice', '外研社版必修第二册 U1 · passage', 2, 'Today I''ll show you how to make a quick and tasty fried rice. First, heat a little oil in a pan. When the oil is hot, add an egg and stir it quickly. Next, add your cold rice and mix it well so that each grain is covered. Then add some chopped vegetables and a spoonful of soy sauce for flavour. Cook everything for two or three minutes over a high heat. Finally, add a little salt if you need to, and serve it hot. It''s so easy that you needn''t be a chef to get it right!', '教你做快手炒饭:先在锅里热点油;油热后打入鸡蛋快速翻炒;再加入冷米饭拌匀,让每粒米都裹上;然后加些切碎的蔬菜和一勺酱油提味;大火炒两三分钟;最后按需加点盐,趁热上桌。非常简单,不必当厨师也能做好。', 'uk_female', '[{"q":"What dish is the speaker making?","type":"choice","answer":"B","options":["Noodle soup.","Fried rice.","Roast beef.","A fruit salad."]},{"q":"What do you add first when the oil is hot?","type":"choice","answer":"C","options":["The rice.","The vegetables.","An egg.","The salt."]},{"q":"What is added to give flavour?","type":"choice","answer":"D","options":["A cup of sugar.","Some honey.","A slice of cheese.","A spoonful of soy sauce."]},{"q":"How long do you cook everything over high heat?","type":"choice","answer":"A","options":["Two or three minutes.","Half an hour.","A whole hour.","Ten seconds."]},{"q":"What does the speaker say about the dish?","type":"choice","answer":"B","options":["It takes a whole day.","It is easy enough for anyone to make.","Only a chef can make it.","It needs special tools."]}]'::jsonb, '[]'::jsonb, 'short', 'required2', 'U1', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·对话 Planning a Family Dinner', '外研社版必修第二册 U1 · dialogue', 3, 'Anna: My parents are coming for dinner on Saturday. What should we cook?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U1 听力·独白 Don''t Skip Breakfast', '外研社版必修第二册 U1 · passage', 2, 'Many students skip breakfast because they are in a hurry, but this is not a good habit. A good breakfast gives you energy and helps you stay awake in class. You needn''t cook anything fancy. A bowl of yoghurt with fresh fruit, or some toast with honey, takes only a few minutes. Try to avoid sugary drinks in the morning, because too much sugar can make you feel tired later. Remember, what you eat at the start of the day really matters, so don''t rush out with an empty stomach.', '许多学生因匆忙而不吃早餐,这是坏习惯。好的早餐能提供能量、帮助你上课保持清醒;不必做花哨的东西,一碗酸奶配新鲜水果、或几片抹蜂蜜的吐司只需几分钟;早上要少喝含糖饮料,糖太多会让你之后犯困;记住一天之初吃什么很重要,别空着肚子匆匆出门。', 'uk_male', '[{"q":"Why do many students skip breakfast?","type":"choice","answer":"D","options":["Because they hate all food.","Because there is no food at home.","Because doctors tell them to.","Because they are in a hurry."]},{"q":"What does a good breakfast do?","type":"choice","answer":"A","options":["It gives energy and helps you stay awake.","It makes you sleepy.","It saves you money.","It cleans your teeth."]},{"q":"What quick breakfast does the speaker suggest?","type":"choice","answer":"B","options":["A large fried meal.","Yoghurt with fruit, or toast with honey.","A bowl of cold chips.","Only a cup of black coffee."]},{"q":"What should you avoid in the morning?","type":"choice","answer":"C","options":["Fresh fruit.","Plain water.","Sugary drinks.","Toast with honey."]},{"q":"What is the speaker''s main message?","type":"choice","answer":"D","options":["Breakfast is a waste of time.","You should eat as much sugar as possible.","Cooking breakfast takes hours.","The first meal of the day is important."]}]'::jsonb, '[]'::jsonb, 'short', 'required2', 'U1', 'fltrp');
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write a Recipe for Your Favourite Dish(为你最爱的一道菜写食谱)', 'My Favourite Dish: Tomato and Egg', '请用英语为你最喜欢的一道家常菜写一份约80词的食谱,内容包括:① 这道菜的名字和一句简单介绍;② 所需配料(列出3-5种);③ 分步骤的做法(用 First / Next / Then / Finally 等顺序词和祈使句)。注意:步骤清楚、动词用对、首字母大写。', 'Write a recipe (about 80 words) for your favourite home dish. Include: 1) the name of the dish and one sentence about it; 2) the ingredients you need (list 3-5); 3) the steps for making it, using imperative verbs and order words such as First, Next, Then and Finally.', '["写出菜名 + 一句简介(My favourite dish is … / It is easy to make.)","列出配料(You will need …)","分步做法,用祈使句 + 顺序词(First, heat the oil. Next, add …)","动词正确、步骤清楚、便于跟做"]'::jsonb, 70, 100, 'My favourite dish is tomato and egg. It is quick, healthy and loved by my whole family. You will need three eggs, two tomatoes, a little oil, some salt and a spoonful of sugar. First, beat the eggs and cut the tomatoes into small pieces. Next, heat the oil in a pan and cook the eggs until they are soft. Then add the tomatoes, the salt and the sugar, and stir everything well. Finally, cook for two more minutes and serve it hot with rice.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["My favourite dish is tomato and egg, and it is loved by my whole family.","You will need three eggs, two tomatoes, a little oil and some salt.","First, beat the eggs and cut the tomatoes into small pieces.","Finally, cook for two more minutes and serve it hot with rice."]'::jsonb, '[{"wrong":"First, you heat the oil and add the egg.","correct":"First, heat the oil and add the egg.","note":"食谱步骤用祈使句,直接用动词原形,不加 you。"},{"wrong":"Add the tomatoes and cooking for two minutes.","correct":"Add the tomatoes and cook for two minutes.","note":"两个并列的祈使动词都用原形,不用 -ing。"},{"wrong":"You will need three egg and two tomato.","correct":"You will need three eggs and two tomatoes.","note":"可数名词复数要加 -s。"}]'::jsonb, '【食谱结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required2', 'U1', '{"title":"情态动词(1)义务与建议速查","intro":"本单元的情态动词都和\"该不该做、必不必须做\"有关。记住三组:义务(must / have to)、建议(should / ought to)、否定(mustn''t=禁止 ≠ needn''t / don''t have to=不必)。判断口诀:看语境是\"必须\"\"应该\"\"禁止\"还是\"不必\",再选对应的词。","table":{"headers":["情态动词","意义 / 用法 / 例句"],"rows":[["must","必须(说话人自己的强烈必要、坚持):You must try this dish!"],["have to","不得不(规则、医嘱、客观情况等外部要求):You have to book a table first."],["should / ought to","应该(建议、忠告,语气较弱):You should eat more fresh fruit."],["mustn''t","一定不要、禁止(不允许/危险/失礼):You mustn''t eat those berries."],["needn''t / don''t have to","不必、没必要(做不做都行):You needn''t cook tonight."]]},"specialRules":[{"rule":"must 强调说话人内心的必要;have to 强调外部强加的要求","mark":"I must apologise. / I have to wear a uniform."},{"rule":"mustn''t ≠ needn''t:前者\"禁止\",后者\"不必\",意义完全相反","mark":"mustn''t=别做 / needn''t=可不做"},{"rule":"must 的过去和将来常借 have to:had to / will have to","mark":"Yesterday I had to cook."},{"rule":"回答 Must I…? 时,否定常用 No, you needn''t. 而非 No, you mustn''t.","mark":"needn''t=不必 √"}],"why":["情态动词本身不随人称变化(he must,不是 he musts);它后面永远跟动词原形,所以重点全在\"选哪个词\"——看语境要表达的是必须、应该、禁止还是不必。"],"gaokaoPoints":["mustn''t(禁止)与 needn''t / don''t have to(不必)的区别是高频考点,常在语法填空和完形中出现。","must(内在必要/推断)vs have to(外在要求)的语境辨析;过去式只能用 had to。"],"examVsReal":[{"exam":"You mustn''t be late.(考试:表禁止/强劝阻)","real":"Don''t be late! / You can''t be late.","note":"口语里禁止更常用 can''t 或直接祈使句"},{"exam":"You needn''t worry.(考试:表不必)","real":"You don''t have to worry. / Don''t worry.","note":"日常口语里 don''t have to 比 needn''t 更常见"}]}'::jsonb, 'fltrp');
